CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL NOT NULL DEFAULT 0, c1 NUMERIC COLLATE NOCASE, c2 BLOB);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(-253.3024, x'2b74', 'psi');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10) COLLATE NOCASE, c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT, c3 BLOB, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES('delta', 0, NULL, 495, 5);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(148.65, 'upsilon', -708, 'MU', 3);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 REAL NOT NULL DEFAULT 0, c1 REAL COLLATE NOCASE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, ref) VALUES(1e-7, NULL, 3);
INSERT OR IGNORE INTO t2(c0, c1, ref) VALUES(0, -394, 3);
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', 0, 2), instr('tau', 'über'), replace('tau', 'é', '_'), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE '%a_', 'tau' GLOB '?', char(82, 252), 'tau' || 'über', 'tau' < 'über', 'tau' = 'über' COLLATE NOCASE;
SELECT length('beta'), upper('beta'), lower('beta'), substr('beta', -2, 1), instr('beta', 'Ελλάδα'), replace('beta', 'a', 'XY'), trim('beta'), ltrim('beta', 'ab'), hex('beta'), quote('beta'), unicode('beta'), 'beta' LIKE '%a_', 'beta' GLOB '?', char(77, 424), 'beta' || 'Ελλάδα', 'beta' < 'Ελλάδα', 'beta' = 'Ελλάδα' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', -2, 3), instr('', 'omicron'), replace('', 'a', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%', '' GLOB '*[a-m]*', char(85, 560), '' || 'omicron', '' < 'omicron', '' = 'omicron' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', -2, 5), instr('nu', 'delta'), replace('nu', 'e', '_'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '_', 'nu' GLOB 'a*', char(78, 409), 'nu' || 'delta', 'nu' < 'delta', 'nu' = 'delta' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', -1, 3), instr('iota', 'nu'), replace('iota', '', 'XY'), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE 'A%', 'iota' GLOB '*[a-m]*', char(73, 889), 'iota' || 'nu', 'iota' < 'nu', 'iota' = 'nu' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 4, 0), instr('', '42'), replace('', '', '_'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%', '' GLOB '*[a-m]*', char(66, 829), '' || '42', '' < '42', '' = '42' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 2, 1), instr('zeta', 'upsilon'), replace('zeta', 'é', ''), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '_', 'zeta' GLOB '?', char(77, 825), 'zeta' || 'upsilon', 'zeta' < 'upsilon', 'zeta' = 'upsilon' COLLATE NOCASE;
SELECT a.id, b.id, a.c1, b.ref FROM t2 a LEFT JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 15;
SELECT count(*) FROM t2 a JOIN t2 b USING(id) WHERE a.abs(c1);
